import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.BSwSpTvy.js";const u=JSON.parse('{"title":"⚡ LSP Symbol Search","description":"","frontmatter":{},"headers":[],"relativePath":"features/lsp.md","filePath":"features/lsp.md"}'),o={name:"features/lsp.md"};function n(i,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="⚡-lsp-symbol-search" tabindex="-1">⚡ LSP Symbol Search <a class="header-anchor" href="#⚡-lsp-symbol-search" aria-label="Permalink to &quot;⚡ LSP Symbol Search&quot;">​</a></h1><p>The standard Zed AI agent relies extensively on regex-driven background indexing to traverse your codebase. While functional for small setups, indexing massive monolithic frameworks causes significant CPU spikes, laptop heat, and delayed search results.</p><p>This custom fork completely rips out the regex strategy.</p><h2 id="native-language-server-protocol-lsp-integration" tabindex="-1">Native Language Server Protocol (LSP) Integration <a class="header-anchor" href="#native-language-server-protocol-lsp-integration" aria-label="Permalink to &quot;Native Language Server Protocol (LSP) Integration&quot;">​</a></h2><p>Language Servers already hold an encyclopedic, purely typed understanding of your code hierarchy (e.g., <code>rust-analyzer</code> for Rust, <code>pyright</code> for Python, <code>gopls</code> for Go).</p><p>This fork intercepts the agent&#39;s context requests and routes them directly to the native LSP layer.</p><h3 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><ul><li><strong>Zero Background Indexing</strong>: Eliminates the persistent background parsing threads. CPU stays entirely flat until you actively ask a question.</li><li><strong>Perfect Accuracy</strong>: The agent understands references, type traits, and implementations rather than just fuzzy text matching.</li><li><strong>Instant Synchronization</strong>: As long as the LSP is attached, the AI agent has the absolutely latest representation of the code exactly as you type it.</li></ul>',8)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
